exec('import csv,os,requests\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip())\nrows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]\nlatest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\nselected=[r for r in latest.values() if r["signal"] in ("ACHAT","SURCHAUFFE","SURVEILLANCE HAUTE","FAIBLESSE FORTE")]\nselected.sort(key=lambda r:(r["date"],int(r["score"])),reverse=True)\nlines=["INVESTMENT ASSISTANT","Derniere cloture disponible par marche",""]\nfor r in selected:\n devise="EUR" if r["ticker"].endswith((".PA",".AS")) else "USD"\n lines.append(r["signal"]+" | "+r["ticker"]+" | Date "+r["date"]+" | Cloture J-1 "+r["price"]+" "+devise+" | Score "+r["score"]+"/100 | Var5j "+r["var5"]+"% | RSI "+r["rsi14"]+" | RVOL "+r["rvol"])\nif not selected: lines.append("Aucun signal prioritaire.")\nlines.extend(["","PORTEFEUILLE VIRTUEL"])\npositions=list(csv.DictReader(open("virtual_portfolio.csv",encoding="utf-8"))) if os.path.exists("virtual_portfolio.csv") else []\ntotal_invested=sum(float(p.get("invested_eur") or 0) for p in positions)\ntotal_value=sum(float(p.get("current_value_eur") or 0) for p in positions)\nfor p in positions:\n pnl=float(p.get("pnl_eur") or 0); pct=float(p.get("pnl_pct") or 0); signe="+" if pnl>=0 else ""; devise=p.get("currency","EUR")\n if p.get("status")=="OPEN": lines.append("OUVERT | "+p["ticker"]+" | Entree "+p["entry_price"]+" "+devise+" | Dernier "+p["last_price"]+" "+devise+" | Valeur "+p["current_value_eur"]+" EUR | PnL "+signe+format(pnl,".2f")+" EUR ("+signe+format(pct,".2f")+"%) | Objectif "+p["target_price"]+" | Stop "+p["stop_price"])\n elif p.get("status")=="CLOSED": lines.append("FERME | "+p["ticker"]+" | Entree "+p["entry_price"]+" "+devise+" | Sortie "+p["exit_price"]+" "+devise+" | PnL "+signe+format(pnl,".2f")+" EUR ("+signe+format(pct,".2f")+"%) | Motif "+p["exit_reason"])\n elif p.get("status")=="PENDING": lines.append("EN ATTENTE | "+p["ticker"]+" | Signal "+p["signal_date"]+" | Achat virtuel prevu a ouverture J")\ntotal_pnl=total_value-total_invested; total_pct=(total_pnl/total_invested*100) if total_invested else 0; signe="+" if total_pnl>=0 else ""\nlines.extend(["","TOTAL | Capital "+format(total_invested,".2f")+" EUR | Valeur "+format(total_value,".2f")+" EUR | PnL "+signe+format(total_pnl,".2f")+" EUR ("+signe+format(total_pct,".2f")+"%)","",""Analyse experimentale en paper trading. Aucun ordre reel."])\nmessage="\\n\\n".join(lines)\nr=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":message},timeout=30)\nprint("Telegram alert:",r.status_code,r.json().get("ok"))')
